export function sceneryForIsland(islandId: string): SceneryProp[] {
  return SCENERY.filter((s) => s.islandId === islandId);
}

export function sceneryWorldPosition(
  prop: SceneryProp,
  islandPosition: { x: number; y: number }
): { x: number; y: number } {
  return { x: islandPosition.x + prop.offset.x, y: islandPosition.y + prop.offset.y };
}
